package com.tracksphere.interfaces.rest;
import com.tracksphere.application.attendance.*; import com.tracksphere.application.attendance.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/attendance") @RequiredArgsConstructor public class AttendanceController { private final AttendanceService service; @PostMapping("/clock-in") public AttendanceResponse clockIn(@AuthenticationPrincipal UUID userId){return service.clockIn(userId);}@PostMapping("/clock-out") public AttendanceResponse clockOut(@AuthenticationPrincipal UUID userId){return service.clockOut(userId);}@GetMapping("/today") public Optional<AttendanceResponse> today(@AuthenticationPrincipal UUID userId){return service.today(userId);}@GetMapping("/report") public List<AttendanceResponse> report(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant to,@RequestParam(required=false) String search){return service.report(from,to,search);} }
